from pathlib import Path
import csv, hashlib, json, shutil
root=Path('kaggle_release/continuitybench_v1')
if root.exists(): raise SystemExit(f'refusing to overwrite existing {root}')
root.mkdir(parents=True)
for sub in ('data','results','analysis','metadata'):(root/sub).mkdir()
# Exact source-of-truth files copied without rewriting.
shutil.copy2('data/generated/continuitybench_v1.jsonl',root/'data/continuitybench_v1.jsonl')
shutil.copy2('reports/generated/current/analysis_20261021/per_case_analysis.csv',root/'results/per_case_results.csv')
for name in ('aggregate_metrics.csv','category_breakdown.csv','difficulty_breakdown.csv','paired_comparisons.csv'):
    shutil.copy2('reports/generated/current/analysis_20261021'/Path(name),root/'analysis'/name)
shutil.copy2('reports/generated/current/analysis_20261021/analysis_report.md',root/'analysis/analysis_report.md')
shutil.copy2('reports/generated/current/analysis_20261021/validation_report.md',root/'analysis/validation_report.md')
# Keep diagnostic evidence explicitly separate from clean benchmark inputs.
shutil.copy2('reports/generated/current/cross_model_handoff_ollama_llama31_qwen3_source_retrieval_audit_20261020_full.json',root/'metadata/source_experiment_manifest.json')
# schema and data dictionary
schema='''# ContinuityBench v1 Schema\n\nEach JSONL line is one case. `case_id` is stable. `source_conversation` is an ordered list of `{role, content}` turns. `handoff_task` is the model-facing task. `required_facts`, `required_constraints`, and `superseded_facts` are evaluator labels. `expected_continuity_state` is gold evaluator data and must not be supplied to evaluated models. `failure_categories`, `difficulty_level`, `scenario_types`, and `scenario_family_id` describe the case. `evaluation_criteria` contains evaluator annotations.\n\nThe published file preserves the repository's existing schema and values. It contains gold labels for reproducible evaluation; users must keep gold fields out of model prompts.\n'''
(root/'data/schema.md').write_text(schema,encoding='utf8')
dict_text='''# Data Dictionary\n\n| Field | Meaning | Model-facing? |\n|---|---|---|\n| `case_id` | Stable case identifier | No |\n| `source_conversation` | Ordered source turns | Yes, through `build_model_input` |\n| `handoff_task` | Handoff question/task | Yes |\n| `required_facts` | Gold required facts | No |\n| `required_constraints` | Gold constraints | No |\n| `superseded_facts` | Gold historical facts | No |\n| `irrelevant_distractor_facts` | Gold distractor annotations | No |\n| `expected_continuity_state` | Gold state and provenance | No |\n| `failure_categories` | Scenario labels | No |\n| `difficulty_level` | Difficulty label | No |\n| `evaluation_criteria` | Evaluator-only criteria | No |\n| `scenario_types` | Scenario composition | No |\n| `scenario_family_id` | Group split family | No |\n\nThe result CSV contains condition metrics and per-case differences. Retrieval evidence is intentionally excluded from the clean result CSV; it remains diagnostic-only in the source experiment manifest.\n'''
(root/'data/data_dictionary.md').write_text(dict_text,encoding='utf8')
# hashes and provenance
files=[p for p in root.rglob('*') if p.is_file()]
def sha(p):
 h=hashlib.sha256(); h.update(p.read_bytes()); return h.hexdigest()
meta={'package_version':'continuitybench_v1_kaggle_20261021','dataset_version':'continuitybench_v1','case_count':84,'source_dataset':'data/generated/continuitybench_v1.jsonl','source_result':'reports/generated/current/cross_model_handoff_ollama_llama31_qwen3_source_retrieval_audit_20261020_full.json','source_analysis':'reports/generated/current/analysis_20261021','model_a':'Ollama llama3.1:8b','model_b':'Ollama qwen3:4b','backend':'local Ollama','condition_names':['transfer','no_transfer','source_retrieval'],'source_retrieval':'deterministic lexical BM25, k=5, positive-score turns only','license_status':'Not established in source repository; owner must confirm redistribution license before publication.','sensitive_data_review':'Synthetic-looking names, references, and identifiers are present; owner should confirm no real personal or confidential data before public upload.','files':{str(p.relative_to(root)):sha(p) for p in files}}
(root/'metadata/provenance.json').write_text(json.dumps(meta,indent=2),encoding='utf8')
(root/'README.md').write_text('''# ContinuityBench v1\n\nContinuityBench is a frozen 84-case dataset for conversational continuity and two-stage model handoff evaluation. This package is prepared as a Kaggle Dataset upload, not a competition entry.\n\n## Contents\n\n- `data/continuitybench_v1.jsonl`: original 84-case JSONL dataset. It includes gold evaluator fields; do not expose those fields to evaluated models.\n- `data/schema.md`, `data/data_dictionary.md`: schema and field definitions.\n- `results/per_case_results.csv`: per-case metrics from the completed local Llama-to-Qwen source-retrieval run.\n- `analysis/`: aggregate, paired, category, and difficulty analyses.\n- `metadata/provenance.json`: package metadata and SHA-256 hashes.\n- `metadata/source_experiment_manifest.json`: diagnostic experiment manifest, kept separate from clean benchmark inputs.\n\n## Experiment\n\nThe completed run used Ollama `llama3.1:8b` as Model A and `qwen3:4b` as Model B. Conditions were transfer artifact, no transfer, and lexical source retrieval. Source retrieval ranked the complete source conversation with deterministic BM25 using the handoff task as query and `k=5`; it is not semantic retrieval.\n\nThe analysis uses the existing metric definitions without modification: `fact_preservation`, `stale_fact_error_rate`, `contradiction_rate`, and `answer_required_fact_coverage`. The metrics are exact-string or structured-set measures and should not be read as semantic validity.\n\n## Limitations\n\nThis is one local run, not evidence of generalization or statistical superiority. Both models ran in one local Ollama environment. Exact-string matching can penalize paraphrases. Zero contradiction or stale-fact error does not prove complete correctness. Human review and owner confirmation of licensing/redistribution permissions remain publication responsibilities.\n\n## Notebook\n\nUse `continuitybench_analysis.ipynb` with this package as the Kaggle input directory. It performs offline validation and descriptive analysis only; it does not call Ollama or any API.\n''',encoding='utf8')
print(root)
